      readDemonHuntTool(wrap({ name: "demon_hunt", args: { target_id: 1, abstain: false } })),
    ).toBeNull();
    expect(isDemonHunterPreset(wrap(board(12, "slaughter_city")))).toBe(false);
    expect(reads).toBe(0);
